import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"SetTargetPos 设置工件目标位置","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/14. 传送带跟随指令/SetTargetPos.md","filePath":"3. 指令/14. 传送带跟随指令/SetTargetPos.md","lastUpdated":1778862643000}'),d={name:"3. 指令/14. 传送带跟随指令/SetTargetPos.md"};function s(h,t,n,i,l,_){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="settargetpos-设置工件目标位置" tabindex="-1">SetTargetPos 设置工件目标位置 <a class="header-anchor" href="#settargetpos-设置工件目标位置" aria-label="Permalink to &quot;SetTargetPos 设置工件目标位置&quot;">​</a></h1><p>该指令用于给指定的传送带发送工件的位置信息，从而让机器人完成传送带跟随运动。在传送带界面中的触发类型选择为非视觉触发类型才可执行该指令。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetTargetPos(Coord, P)</p><p>SetTargetPos(坐标系, 目标位置)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Coord</td><td>SYNCOORD 变量</td><td>当前工件位置信息所参考的动坐标系，需与传送带配置界面中启用的动坐标系一致</td><td>必填</td></tr><tr><td>P</td><td>CPOS 变量</td><td>工件相对于 SYNCOORD 坐标系原点的偏移量。该参数中仅 x、y、a 有效</td><td>必填</td></tr></tbody></table>',8)])])}const P=e(d,[["render",s]]);export{c as __pageData,P as default};
